import ingredientData from './data/ingredients.json';
import type { IngredientHit } from '../../pantry/types';

/**
 * Ingredient lookup over the @fr/refdata canonical ingredient names/aliases.
 * data/ingredients.json is a slim snapshot generated by gen-seed.mjs (apps/web cannot bundle
 * @fr/refdata's fs-based loader); ingredients.test.ts fails if it drifts from @fr/refdata.
 */
export interface IngredientRecord extends IngredientHit {
  aliases: string[];
}

export interface IngredientLookup {
  search(query: string, limit?: number): IngredientHit[];
  get(id: string): IngredientRecord | undefined;
  findByName(name: string): IngredientRecord | undefined;
}

const norm = (s: string): string => s.toLowerCase().trim();

export function createIngredientLookup(records: readonly IngredientRecord[]): IngredientLookup {
  const byId = new Map(records.map((r) => [r.id, r]));
  const byName = new Map<string, IngredientRecord>();
  for (const r of records) byName.set(norm(r.name), r);
  for (const r of records) for (const a of r.aliases) if (!byName.has(norm(a))) byName.set(norm(a), r);

  return {
    get: (id) => byId.get(id),
    findByName: (name) => byName.get(norm(name)),
    search(query, limit = 8) {
      const q = norm(query);
      if (!q) return [];
      const scored: { r: IngredientRecord; s: number }[] = [];
      for (const r of records) {
        const n = norm(r.name);
        let s = 0;
        if (n === q) s = 100;
        else if (n.startsWith(q)) s = 80;
        else if (n.split(/\s+/).some((w) => w.startsWith(q))) s = 60;
        else if (r.aliases.some((a) => norm(a).startsWith(q))) s = 50;
        else if (n.includes(q)) s = 30;
        else if (r.aliases.some((a) => norm(a).includes(q))) s = 20;
        if (s) scored.push({ r, s });
      }
      scored.sort((a, b) => b.s - a.s || a.r.name.length - b.r.name.length || a.r.name.localeCompare(b.r.name));
      return scored.slice(0, limit).map(({ r }) => ({ id: r.id, name: r.name, category: r.category }));
    },
  };
}

export const defaultIngredientLookup = (): IngredientLookup =>
  createIngredientLookup(ingredientData as IngredientRecord[]);
